@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 0 0% 99%;
    --foreground: 220 13% 18%;

    --card: 0 0% 100%;
    --card-foreground: 220 13% 18%;

    --popover: 0 0% 100%;
    --popover-foreground: 220 13% 18%;

    --primary: 239 70% 58%;
    --primary-foreground: 0 0% 100%;

    --secondary: 220 14% 96%;
    --secondary-foreground: 220 13% 18%;

    --muted: 220 14% 96%;
    --muted-foreground: 220 9% 46%;

    --accent: 220 14% 96%;
    --accent-foreground: 220 13% 18%;

    --destructive: 0 72% 51%;
    --destructive-foreground: 0 0% 100%;

    --success: 142 71% 45%;
    --success-foreground: 0 0% 100%;

    --warning: 38 92% 50%;
    --warning-foreground: 0 0% 100%;

    --border: 220 13% 93%;
    --input: 220 13% 93%;
    --ring: 239 70% 58%;

    --radius: 0.75rem;

    --sidebar-background: 222 47% 11.2%;
    --sidebar-foreground: 220 10% 58%;
    --sidebar-primary: 239 70% 62%;
    --sidebar-primary-foreground: 0 0% 100%;
    --sidebar-accent: 239 70% 62%;
    --sidebar-accent-foreground: 0 0% 100%;
    --sidebar-border: 222 20% 18%;
    --sidebar-ring: 239 70% 62%;

    --topbar-height: 60px;

    --mac-red: 0 80% 67%;
    --mac-yellow: 38 100% 59%;
    --mac-green: 133 53% 52%;
  }

  .dark {
    --background: 220 13% 9%;
    --foreground: 220 13% 90%;
    --card: 220 13% 12%;
    --card-foreground: 220 13% 90%;
    --popover: 220 13% 12%;
    --popover-foreground: 220 13% 90%;
    --primary: 239 70% 65%;
    --primary-foreground: 0 0% 100%;
    --secondary: 220 13% 18%;
    --secondary-foreground: 220 13% 90%;
    --muted: 220 13% 16%;
    --muted-foreground: 220 9% 55%;
    --accent: 220 13% 18%;
    --accent-foreground: 220 13% 90%;
    --destructive: 0 72% 51%;
    --destructive-foreground: 0 0% 100%;
    --border: 220 13% 22%;
    --input: 220 13% 22%;
    --ring: 239 70% 65%;
  }
}

@layer base {
  * {
    @apply border-border;
  }

  html {
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  body {
    @apply bg-background text-foreground font-sans;
    font-family: 'Inter', system-ui, sans-serif;
    font-feature-settings: 'cv11', 'ss01';
  }

  /* Refined focus rings */
  *:focus-visible {
    @apply outline-none ring-2 ring-primary/25 ring-offset-2 ring-offset-background;
  }
}

@layer utilities {
  /* Subtle text rendering for headings */
  .text-balance {
    text-wrap: balance;
  }

  /* Extra-small text size (10px) for badges and meta labels */
  .text-2xs {
    font-size: 0.625rem;
    line-height: 1rem;
  }

  /* Thin scrollbar for data-heavy panels */
  .scrollbar-thin {
    scrollbar-width: thin;
    scrollbar-color: hsl(var(--border)) transparent;
  }
}

/* Custom scrollbar (WebKit) */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background-color: hsl(var(--border));
  border-radius: 3px;
}

