import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { ScanLine } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { PAGE_TYPES } from "@/lib/constants";
import { cn } from "@/lib/utils";
import type { PageType } from "@/types";

interface UrlInputProps {
  showPageType?: boolean;
  buttonText?: string;
  size?: "default" | "lg";
  className?: string;
  onSubmit?: (url: string, pageType: PageType) => void;
}

export const UrlInput = React.forwardRef<HTMLFormElement, UrlInputProps>(function UrlInput({
  showPageType = false,
  buttonText = "Analyze Now",
  size = "default",
  className,
  onSubmit,
}, ref) {
  const [url, setUrl] = useState("");
  const [pageType, setPageType] = useState<PageType>("landing");
  const navigate = useNavigate();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = url.trim();
    if (!trimmed) return;

    // Normalize: add https:// if missing
    const normalized = /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`;

    if (onSubmit) {
      onSubmit(normalized, pageType);
    } else {
      navigate(`/scan?url=${encodeURIComponent(normalized)}&type=${pageType}`);
    }
  };

  const isLarge = size === "lg";

  return (
    <form ref={ref} onSubmit={handleSubmit} className={cn("w-full", className)}>
      <div className={cn("flex gap-2", isLarge ? "flex-col sm:flex-row" : "flex-row")}>
        <div className="relative flex-1">
          <Input
            type="url"
            placeholder="https://your-website.com/landing-page"
            value={url}
            onChange={(e) => setUrl(e.target.value)}
            className={cn(
              "border-border/50 bg-card pr-4 pl-4 text-foreground placeholder:text-muted-foreground focus-visible:ring-primary/20 focus-visible:border-primary",
              isLarge ? "h-14 text-base rounded-xl" : "h-10 text-sm rounded-lg"
            )}
          />
        </div>
        {showPageType && (
          <Select value={pageType} onValueChange={(v) => setPageType(v as PageType)}>
            <SelectTrigger
              className={cn(
                "w-40 border-border/50 bg-card",
                isLarge ? "h-14 rounded-xl" : "h-10 rounded-lg"
              )}
            >
              <SelectValue placeholder="Page type" />
            </SelectTrigger>
            <SelectContent>
              {PAGE_TYPES.map((type) => (
                <SelectItem key={type.value} value={type.value}>
                  {type.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}
        <Button
          type="submit"
          className={cn(
            "shrink-0 font-semibold",
            isLarge
              ? "h-14 px-8 text-base rounded-xl"
              : "h-10 px-5 text-sm rounded-lg"
          )}
        >
          <ScanLine className={cn("mr-2", isLarge ? "h-5 w-5" : "h-4 w-4")} />
          {buttonText}
        </Button>
      </div>
    </form>
  );
});

