import { useRef } from "react";
import { motion, useInView } from "framer-motion";
import { CRO_PILLARS } from "@/lib/constants";

const fadeUp = {
  hidden: { opacity: 0, y: 20 },
  show: { opacity: 1, y: 0, transition: { duration: 0.45, ease: [0.25, 0.46, 0.45, 0.94] } },
};

export default function Pillars() {
  const ref = useRef<HTMLDivElement>(null);
  const isInView = useInView(ref, { once: true, margin: "-80px" });

  return (
    <section className="py-24 bg-slate-50" id="pillars">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Header */}
        <motion.div
          ref={ref}
          initial="hidden"
          animate={isInView ? "show" : "hidden"}
          variants={{ hidden: {}, show: { transition: { staggerChildren: 0.1 } } }}
          className="mb-12 max-w-2xl"
        >
          <motion.p
            variants={fadeUp}
            className="text-xs font-semibold uppercase tracking-widest text-indigo-600 mb-3"
          >
            The 7 CRO pillars
          </motion.p>
          <motion.h2
            variants={fadeUp}
            className="text-3xl sm:text-4xl font-bold text-slate-900 leading-tight"
          >
            Every dimension that drives conversions.
          </motion.h2>
          <motion.p variants={fadeUp} className="mt-4 text-lg text-slate-500">
            ConvertScan scores each pillar independently so you know exactly
            where to focus first.
          </motion.p>
        </motion.div>

        {/* Pillar grid */}
        <motion.div
          initial="hidden"
          animate={isInView ? "show" : "hidden"}
          variants={{
            hidden: {},
            show: { transition: { staggerChildren: 0.07, delayChildren: 0.15 } },
          }}
          className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4"
        >
          {CRO_PILLARS.map((pillar) => {
            const Icon = pillar.icon;
            const weightPct = Math.round(pillar.weight * 100);

            return (
              <motion.div
                key={pillar.key}
                variants={fadeUp}
                whileHover={{ y: -4, boxShadow: "0 16px 40px rgba(0,0,0,0.08)" }}
                transition={{ duration: 0.2 }}
                className="group relative bg-white/70 backdrop-blur-sm border border-white/80 rounded-2xl p-5 shadow-sm hover:bg-white transition-all duration-200 cursor-default"
              >
                {/* Weight badge */}
                <div className="absolute top-4 right-4">
                  <span className="text-xs font-semibold text-indigo-600 bg-indigo-50 border border-indigo-100 px-2 py-0.5 rounded-full">
                    {weightPct}%
                  </span>
                </div>

                {/* Icon */}
                <div className="w-10 h-10 rounded-xl bg-indigo-50 flex items-center justify-center mb-4 group-hover:bg-indigo-100 transition-colors">
                  <Icon className="w-5 h-5 text-indigo-600" strokeWidth={1.75} />
                </div>

                {/* Text */}
                <h3 className="text-sm font-semibold text-slate-900 mb-1.5 leading-snug">
                  {pillar.label}
                </h3>
                <p className="text-xs text-slate-500 leading-relaxed">
                  {pillar.description}
                </p>
              </motion.div>
            );
          })}

          {/* Empty slot filler for 4+3 grid symmetry on large screens */}
          <div className="hidden lg:block" />
        </motion.div>
      </div>
    </section>
  );
}

