              target="_blank"
              rel="noopener noreferrer"
            >
              Boldteq
            </a>
          </p>
        </div>
      </div>
    </footer>
  );
}

export default function LogoBar() {
  const segments = [
    "SaaS Startups",
    "E-commerce",
    "Agencies",
    "Enterprise",
    "DTC Brands",
    "Marketplaces",
