import { useRef } from "react";
import { motion, useInView } from "framer-motion";
import { Link2, Brain, Zap } from "lucide-react";

const STEPS = [
  {
    number: "01",
    icon: Link2,
    title: "Paste your URL",
    description:
      "Drop in any landing page, product page, or homepage URL. No browser extension, no code, no setup required.",
  },
  {
    number: "02",
    icon: Brain,
    title: "AI analyzes 40+ signals",
    description:
      "Our AI scans visual hierarchy, CTA placement, trust signals, copy quality, mobile UX, and Core Web Vitals — all at once.",
  },
  {
    number: "03",
    icon: Zap,
    title: "Get your fix list",
    description:
      "A prioritized list of issues ranked by conversion impact, each with a specific, actionable fix you can implement today.",
  },
];

const fadeUp = {
  hidden: { opacity: 0, y: 24 },
  show: { opacity: 1, y: 0, transition: { duration: 0.5, ease: [0.25, 0.46, 0.45, 0.94] } },
};

export default function HowItWorks() {
  const ref = useRef<HTMLDivElement>(null);
  const isInView = useInView(ref, { once: true, margin: "-80px" });

  return (
    <section className="py-24 bg-white" id="how-it-works">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Header */}
        <motion.div
          ref={ref}
          initial="hidden"
          animate={isInView ? "show" : "hidden"}
          variants={{ hidden: {}, show: { transition: { staggerChildren: 0.1 } } }}
          className="text-center max-w-2xl mx-auto mb-16"
        >
          <motion.p
            variants={fadeUp}
            className="text-xs font-semibold uppercase tracking-widest text-indigo-600 mb-3"
          >
            How it works
          </motion.p>
          <motion.h2
            variants={fadeUp}
            className="text-3xl sm:text-4xl font-bold text-slate-900 leading-tight"
          >
            From URL to fix list in 30 seconds.
          </motion.h2>
          <motion.p variants={fadeUp} className="mt-4 text-lg text-slate-500">
            No onboarding, no configuration, no waiting. Paste a URL and get
            your audit instantly.
          </motion.p>
        </motion.div>

        {/* Steps */}
        <motion.div
          initial="hidden"
          animate={isInView ? "show" : "hidden"}
          variants={{ hidden: {}, show: { transition: { staggerChildren: 0.15, delayChildren: 0.2 } } }}
          className="relative"
        >
          {/* Connecting line (desktop) */}
          <div className="hidden lg:block absolute top-14 left-[calc(16.666%-1px)] right-[calc(16.666%-1px)] h-px bg-gradient-to-r from-transparent via-slate-200 to-transparent" />

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-12 lg:gap-8">
            {STEPS.map((step) => {
              const Icon = step.icon;
              return (
                <motion.div
                  key={step.number}
                  variants={fadeUp}
                  className="flex flex-col items-center text-center lg:items-center"
                >
                  {/* Number circle + icon */}
                  <div className="relative mb-6">
                    <div className="w-28 h-28 rounded-2xl bg-slate-50 border border-slate-100 flex items-center justify-center shadow-sm">
                      <Icon className="w-10 h-10 text-indigo-600" strokeWidth={1.5} />
                    </div>
                    <div className="absolute -top-3 -right-3 w-7 h-7 rounded-full bg-indigo-600 flex items-center justify-center shadow-md shadow-indigo-500/30">
                      <span className="text-xs font-bold text-white">
                        {step.number.replace("0", "")}
                      </span>
                    </div>
                  </div>

                  <h3 className="text-lg font-semibold text-slate-900 mb-2">
                    {step.title}
                  </h3>
                  <p className="text-sm text-slate-500 leading-relaxed max-w-xs">
                    {step.description}
                  </p>
                </motion.div>
              );
            })}
          </div>
        </motion.div>
      </div>
    </section>
  );
}

