  hidden: { opacity: 0, y: 24 },
  show: { opacity: 1, y: 0, transition: { duration: 0.5, ease: [0.25, 0.46, 0.45, 0.94] } },
};

export default function FinalCTA() {
  const ref = useRef<HTMLDivElement>(null);
  const isInView = useInView(ref, { once: true, margin: "-60px" });

  return (
    <section className="relative py-28 overflow-hidden" style={{ background: "linear-gradient(135deg, #0f0f1a 0%, #1e1b4b 50%, #0f172a 100%)" }}>
      {/* Grid background */}
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          backgroundImage: GRID_PATTERN,
          backgroundSize: "48px 48px",
          maskImage: "radial-gradient(ellipse 80% 80% at 50% 50%, black 30%, transparent 100%)",
          WebkitMaskImage: "radial-gradient(ellipse 80% 80% at 50% 50%, black 30%, transparent 100%)",
        }}
      />

      {/* Center glow */}
      <div
        className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[400px] pointer-events-none"
        style={{
          background: "radial-gradient(ellipse, rgba(99,102,241,0.22) 0%, transparent 70%)",
        }}
      />

      <div className="relative max-w-3xl mx-auto px-4 text-center" ref={ref}>
        <motion.div
          initial="hidden"
          animate={isInView ? "show" : "hidden"}
          variants={{ hidden: {}, show: { transition: { staggerChildren: 0.12 } } }}
        >
          <motion.p
            variants={fadeUp}
            className="text-xs font-semibold uppercase tracking-widest text-indigo-400 mb-4"
          >
            Free to start
          </motion.p>

          <motion.h2
            variants={fadeUp}
            className="text-4xl sm:text-5xl font-bold text-white leading-tight mb-6"
          >
            Every hour without a CRO audit
            <br />
            <span className="text-slate-400">costs you conversions.</span>
          </motion.h2>

          <motion.p
            variants={fadeUp}
            className="text-lg text-slate-400 mb-10 max-w-xl mx-auto leading-relaxed"
          >
            Get a full audit of any landing page in 30 seconds. No signup,
            no credit card, no friction.
          </motion.p>

          {/* Input with glow border */}
          <motion.div variants={fadeUp} className="relative max-w-2xl mx-auto">
            {/* Animated gradient ring */}
            <div
              className="absolute -inset-1 rounded-2xl pointer-events-none"
              style={{
                background: "linear-gradient(90deg, rgba(99,102,241,0.6), rgba(139,92,246,0.6), rgba(99,102,241,0.6))",
                backgroundSize: "200% 100%",
                animation: "shimmer 3s linear infinite",
                borderRadius: "1rem",
                filter: "blur(6px)",
                opacity: 0.7,
              }}
            />
            <div className="relative">
              <UrlInput
                size="lg"
                buttonText="Analyze Free"
                className="[&_input]:bg-slate-900/90 [&_input]:border-white/10 [&_input]:text-white [&_input]:placeholder:text-slate-500 [&_input]:rounded-xl [&_button]:bg-indigo-600 [&_button]:hover:bg-indigo-500 [&_button]:text-white [&_button]:border-0"
              />
            </div>
          </motion.div>

          <motion.p
            variants={fadeUp}
            className="mt-5 text-sm text-slate-500"
          >
            No account needed · Results in 30 seconds · 3 free scans per month
          </motion.p>
        </motion.div>
      </div>

      <style>{`
        @keyframes shimmer {
          0% { background-position: 0% 0%; }
          100% { background-position: 200% 0%; }
        }
      `}</style>
    </section>
  );
}

