import { useRef } from "react";
import { motion } from "framer-motion";
import { ArrowRight, CheckCircle2, TrendingUp, AlertTriangle, XCircle } from "lucide-react";
import { UrlInput } from "@/components/shared/UrlInput";
import { ScoreRing } from "@/components/shared/ScoreRing";

/* ── Mock audit data for the browser preview ─────────────────── */

const MOCK_PILLAR_BARS = [
  { label: "CTA Effectiveness", score: 38, color: "#EF4444" },
  { label: "Trust Signals", score: 29, color: "#EF4444" },
  { label: "Value Proposition", score: 72, color: "#22C55E" },
  { label: "Mobile Experience", score: 64, color: "#F59E0B" },
  { label: "Visual Hierarchy", score: 81, color: "#22C55E" },
];

const MOCK_FINDINGS = [
  { severity: "critical" as const, text: "CTA below fold, contrast ratio 3.2:1" },
  { severity: "warning" as const, text: "No social proof above the fold" },
  { severity: "info" as const, text: "Headline uses feature language, not outcomes" },
];

const SEVERITY_DOT: Record<"critical" | "warning" | "info", string> = {
  critical: "bg-red-500",
  warning: "bg-amber-500",
  info: "bg-blue-500",
};

/* ── Grid background pattern ─────────────────────────────────── */

const GRID_PATTERN = `
  linear-gradient(to right, rgba(255,255,255,0.04) 1px, transparent 1px),
  linear-gradient(to bottom, rgba(255,255,255,0.04) 1px, transparent 1px)
`;

/* ── Animation variants ──────────────────────────────────────── */

const fadeUp = {
  hidden: { opacity: 0, y: 20 },
  show: { opacity: 1, y: 0 },
};

const stagger = {
  hidden: {},
  show: { transition: { staggerChildren: 0.12 } },
};

export default function Hero() {
  const ref = useRef<HTMLDivElement>(null);

  return (
    <section
      ref={ref}
      className="relative min-h-screen bg-slate-950 overflow-hidden flex flex-col"
    >
      {/* Background grid */}
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          backgroundImage: GRID_PATTERN,
          backgroundSize: "48px 48px",
          maskImage:
            "radial-gradient(ellipse 80% 60% at 50% 0%, black 40%, transparent 100%)",
          WebkitMaskImage:
            "radial-gradient(ellipse 80% 60% at 50% 0%, black 40%, transparent 100%)",
        }}
      />

      {/* Radial glow from center-top */}
      <div
        className="absolute top-0 left-1/2 -translate-x-1/2 w-[900px] h-[500px] pointer-events-none"
        style={{
          background:
            "radial-gradient(ellipse at top, rgba(99,102,241,0.18) 0%, transparent 70%)",
        }}
      />

      <div className="relative flex-1 flex flex-col items-center justify-start pt-36 pb-0 px-4">
        {/* Badge */}
        <motion.div
          variants={stagger}
          initial="hidden"
          animate="show"
          className="flex flex-col items-center gap-6 max-w-3xl w-full text-center"
        >
          <motion.div variants={fadeUp}>
            <span className="inline-flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-medium bg-indigo-500/10 text-indigo-300 border border-indigo-500/20 ring-1 ring-indigo-500/10">
              <span className="relative flex h-2 w-2">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-indigo-400 opacity-75" />
                <span className="relative inline-flex rounded-full h-2 w-2 bg-indigo-400" />
              </span>
              Trusted by 500+ marketing teams
            </span>
          </motion.div>

          {/* Headline */}
          <motion.h1
            variants={fadeUp}
            className="text-5xl sm:text-6xl lg:text-7xl font-bold text-white leading-[1.08] tracking-tight"
          >
            Stop guessing why
            <br />
            <span className="text-slate-400">visitors leave.</span>
          </motion.h1>

          {/* Subheading */}
          <motion.p
            variants={fadeUp}
            className="text-lg sm:text-xl text-slate-400 max-w-2xl leading-relaxed"
          >
            ConvertScan analyzes any landing page against 7 CRO pillars and 40+
            conversion checks — then gives you a prioritized fix list in 30
            seconds.
          </motion.p>

          {/* URL Input */}
          <motion.div variants={fadeUp} className="w-full max-w-2xl">
            <div className="relative">
              {/* Glow behind input */}
              <div className="absolute -inset-1 rounded-2xl bg-indigo-500/20 blur-lg pointer-events-none" />
              <div className="relative">
                <UrlInput
                  size="lg"
                  buttonText="Analyze Free"
                  className="[&_input]:bg-slate-900/90 [&_input]:border-white/10 [&_input]:text-white [&_input]:placeholder:text-slate-500 [&_input]:rounded-xl [&_button]:bg-indigo-600 [&_button]:hover:bg-indigo-500 [&_button]:text-white [&_button]:border-0"
                />
              </div>
            </div>
          </motion.div>

          {/* Trust micro-copy */}
          <motion.div
            variants={fadeUp}
            className="flex flex-wrap items-center justify-center gap-x-5 gap-y-2 text-sm text-slate-500"
          >
            {["No signup required", "Free forever", "30-second results"].map(
              (item) => (
                <span key={item} className="flex items-center gap-1.5">
                  <CheckCircle2 className="w-3.5 h-3.5 text-slate-600" />
                  {item}
                </span>
              )
            )}
          </motion.div>
        </motion.div>

        {/* Browser mockup */}
        <motion.div
          initial={{ opacity: 0, y: 40 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.55, duration: 0.5, ease: [0.25, 0.46, 0.45, 0.94] }}
          className="relative mt-16 w-full max-w-5xl mx-auto"
        >
          {/* Glow under mockup */}
          <div
            className="absolute -bottom-8 left-1/2 -translate-x-1/2 w-3/4 h-24 pointer-events-none"
            style={{
              background:
                "radial-gradient(ellipse, rgba(99,102,241,0.25) 0%, transparent 70%)",
              filter: "blur(20px)",
            }}
          />

          {/* Browser chrome */}
          <div className="relative rounded-xl overflow-hidden border border-white/10 shadow-2xl shadow-black/60">
            {/* Chrome bar */}
            <div className="bg-slate-900 border-b border-white/[0.06] px-4 py-3 flex items-center gap-3">
              <div className="flex gap-1.5">
                <div className="w-3 h-3 rounded-full bg-red-500/70" />
                <div className="w-3 h-3 rounded-full bg-amber-500/70" />
                <div className="w-3 h-3 rounded-full bg-green-500/70" />
              </div>
              <div className="flex-1 mx-4">
                <div className="bg-slate-800 rounded-md px-3 py-1 text-xs text-slate-500 flex items-center gap-2 max-w-sm mx-auto">
                  <div className="w-3 h-3 rounded-full bg-green-500/60 shrink-0" />
                  app.convertscan.ai/report/abc123
                </div>
              </div>
            </div>

            {/* Report content */}
            <div className="bg-slate-900/80 p-5 sm:p-8">
              <div className="flex flex-col lg:flex-row gap-8">
                {/* Left: Score + URL */}
                <div className="flex flex-col items-center lg:items-start gap-4 lg:w-56 shrink-0">
                  <div>
                    <p className="text-xs text-slate-500 mb-1 text-center lg:text-left">
                      Analyzing
                    </p>
                    <p className="text-sm font-medium text-slate-300 text-center lg:text-left">
                      acme.com/pricing
                    </p>
                  </div>
                  <ScoreRing score={54} size={120} strokeWidth={9} showLabel />
                  <div className="text-center lg:text-left">
                    <p className="text-xs text-slate-500">Overall CRO Score</p>
                    <p className="text-xs text-amber-400 font-medium mt-0.5">
                      3 critical issues found
                    </p>
                  </div>
                </div>

                {/* Right: Pillar bars + findings */}
                <div className="flex-1 space-y-5">
                  {/* Pillar bars */}
                  <div>
                    <p className="text-xs font-medium text-slate-400 mb-3 uppercase tracking-wider">
                      Pillar Scores
                    </p>
                    <div className="space-y-2.5">
                      {MOCK_PILLAR_BARS.map((p) => (
                        <div key={p.label} className="flex items-center gap-3">
                          <span className="text-xs text-slate-400 w-36 shrink-0">
                            {p.label}
                          </span>
                          <div className="flex-1 bg-slate-800 rounded-full h-1.5 overflow-hidden">
                            <div
                              className="h-full rounded-full"
                              style={{
                                width: `${p.score}%`,
                                backgroundColor: p.color,
                              }}
                            />
                          </div>
                          <span
                            className="text-xs font-semibold tabular-nums w-8 text-right"
                            style={{ color: p.color }}
                          >
                            {p.score}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>

                  {/* Findings */}
                  <div>
                    <p className="text-xs font-medium text-slate-400 mb-3 uppercase tracking-wider">
                      Top Findings
                    </p>
                    <div className="space-y-2">
                      {MOCK_FINDINGS.map((f, i) => (
                        <div
                          key={i}
                          className="flex items-start gap-2.5 bg-slate-800/60 rounded-lg px-3 py-2.5"
                        >
                          <span
                            className={`mt-0.5 w-2 h-2 rounded-full shrink-0 ${SEVERITY_DOT[f.severity]}`}
                          />
                          <span className="text-xs text-slate-300 leading-relaxed">
                            {f.text}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </motion.div>
      </div>

      {/* Stats strip */}
      <div className="relative border-t border-white/[0.06] bg-slate-950/50 mt-6">
        <div className="max-w-4xl mx-auto px-4 py-5">
          <div className="flex flex-wrap items-center justify-center gap-6 sm:gap-0 sm:divide-x sm:divide-white/[0.08]">
            {[
              { value: "2,400+", label: "Pages Audited" },
              { value: "7", label: "CRO Pillars" },
              { value: "40+", label: "Checks Per Page" },
            ].map((stat) => (
              <div
                key={stat.label}
                className="flex flex-col items-center px-8 py-1"
              >
                <span className="text-2xl font-bold text-white tabular-nums">
                  {stat.value}
                </span>
                <span className="text-xs text-slate-500 mt-0.5">{stat.label}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

