import { useRef } from "react";
import { motion, useInView } from "framer-motion";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";

const FAQS = [
  {
    question: "What exactly does ConvertScan check?",
    answer:
      "ConvertScan analyzes your page against 7 CRO pillars: Value Proposition clarity, CTA Effectiveness, Trust Signals, Visual Hierarchy, Mobile Experience, Content & Copy quality, and Page Performance. Each pillar runs multiple checks — over 40 in total — covering everything from button contrast ratios to headline clarity to Core Web Vitals.",
  },
  {
    question: "How long does an audit take?",
    answer:
      "Most audits complete in under 30 seconds. ConvertScan takes a screenshot of your page, runs a performance analysis, and sends both to our AI engine for a comprehensive review. Complex pages with heavy JavaScript may take slightly longer.",
  },
  {
    question: "Do I need to install anything?",
    answer:
      "No. ConvertScan works entirely from a URL — no browser extension, no code snippet, no tag manager setup. Paste a URL and get results. That's it.",
  },
  {
    question: "Is it really free?",
    answer:
      "Yes. Every user gets 3 free scans per month with no account required. Free scans include the full CRO score, pillar breakdown, and top 3 findings. Pro and Agency plans unlock unlimited scans, all findings, AI copy rewrites, PDF exports, and score tracking over time.",
  },
  {
    question: "What makes this different from Google PageSpeed?",
    answer:
      "PageSpeed Insights focuses on technical performance — load times, Core Web Vitals, and rendering metrics. ConvertScan covers that too (it's one of our 7 pillars), but also analyzes conversion-specific factors: whether your CTA is visible, whether your headlines communicate value, whether trust signals are present, and whether your visual hierarchy guides visitors toward action.",
  },
  {
    question: "Can I use this for client sites?",
    answer:
      "Absolutely. Many agencies use ConvertScan as part of their client onboarding and reporting workflow. The Agency plan includes white-label PDF exports, multi-client dashboards, and API access for integrating audits into your existing tools.",
  },
  {
    question: "How accurate is the AI analysis?",
    answer:
      "ConvertScan uses Claude's vision and text analysis to evaluate your page the way an experienced CRO consultant would — looking at layout, copy, trust elements, and user flow. It's not a rule-based checker; it understands context. That said, AI analysis is a starting point. We recommend treating findings as expert suggestions to validate with your own A/B tests.",
  },
  {
    question: "Can I export or share reports?",
    answer:
      "Pro and Agency plans include PDF export with your full audit report — pillar scores, all findings, and AI-generated fixes. You can share the PDF directly with your team, clients, or stakeholders. Agency plans also support white-labeling with your own branding.",
  },
];

const fadeUp = {
  hidden: { opacity: 0, y: 20 },
  show: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.45, ease: [0.25, 0.46, 0.45, 0.94] },
  },
};

export default function FAQ() {
  const ref = useRef<HTMLDivElement>(null);
  const isInView = useInView(ref, { once: true, margin: "-80px" });

  return (
    <section className="py-24 bg-white">
      <div className="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Header — left aligned */}
        <motion.div
          ref={ref}
          initial="hidden"
          animate={isInView ? "show" : "hidden"}
          variants={{
            hidden: {},
            show: { transition: { staggerChildren: 0.1 } },
          }}
          className="mb-12"
        >
          <motion.p
            variants={fadeUp}
            className="text-xs font-semibold uppercase tracking-widest text-indigo-600 mb-3"
          >
            FAQ
          </motion.p>
          <motion.h2
            variants={fadeUp}
            className="text-3xl sm:text-4xl font-bold text-slate-900 leading-tight"
          >
            Common questions, straight answers.
          </motion.h2>
        </motion.div>

        {/* Accordion */}
        <motion.div
          initial="hidden"
          animate={isInView ? "show" : "hidden"}
          variants={{
            hidden: {},
            show: { transition: { staggerChildren: 0.06, delayChildren: 0.15 } },
          }}
        >
          <Accordion type="single" collapsible className="w-full">
            {FAQS.map((faq, i) => (
              <motion.div key={i} variants={fadeUp}>
                <AccordionItem
                  value={`item-${i}`}
                  className="border-b border-slate-100"
                >
                  <AccordionTrigger className="text-left text-base font-medium text-slate-900 hover:text-indigo-600 hover:no-underline py-5 gap-4">
                    {faq.question}
                  </AccordionTrigger>
                  <AccordionContent className="text-slate-500 text-sm leading-relaxed">
                    {faq.answer}
                  </AccordionContent>
                </AccordionItem>
              </motion.div>
            ))}
          </Accordion>
        </motion.div>
      </div>
    </section>
  );
}

